const fs = require('fs');
const path = require('path');
const { ICONS, renderIcon } = require('./icons-data.js');

const dir = path.join(__dirname, 'icons');
fs.mkdirSync(dir, { recursive: true });
for (const icon of ICONS) fs.writeFileSync(path.join(dir, `${icon.key}.svg`), renderIcon(icon) + '\n');
console.log(`Wrote ${ICONS.length} icons to ${dir}`);
